sksl:
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float scale;
uniform float angle;
uniform float2 position;
uniform float2 stretch;
uniform float alpha;
uniform float hardness;
uniform float blendMode;
uniform float alphaComp;
uniform float direction;
uniform float shape;
uniform float width;
uniform float sweepInt;
uniform float edgeInt;
uniform float edgeThick;
uniform float offset;
uniform float gradMap;
uniform float gmTri;
layout(color) uniform half4 gmFg;
layout(color) uniform half4 gmMid;
layout(color) uniform half4 gmBg;
uniform float quality;
uniform float autop;
uniform float autoSpeed;
    float qMul() { return quality < 1.5 ? 0.25 : (quality < 2.5 ? 0.5 : (quality < 3.5 ? 1.0 : (quality < 4.5 ? 1.5 : 2.0))); }
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxs) {
        float z = max(scale * 2.0, 0.002);
        p -= position * pxs;
        p = nmRot(p, -radians(angle));
        return p / (z * max(stretch, float2(0.01)));
    }
    float4 nmGradMap(float4 fx) {
        if (!(gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(gmBg.rgb * gmBg.a, gmBg.a), pM = float4(gmMid.rgb * gmMid.a, gmMid.a), pF = float4(gmFg.rgb * gmFg.a, gmFg.a);
        float4 c = (gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * hardness, 0.0, 1.0) * clamp(alpha, 0.0, 1.0);
        float4 b = tex * clamp(alphaComp, 0.0, 1.0);
        float4 o;
        if (int(blendMode) == 0) o = f;
        else if (int(blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(blendMode) == 4) o = float4(b.rgb + f.rgb, max(b.a, f.a));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float prog(float p) { return (autop>0.5) ? p + time * (autoSpeed * 0.5) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float4 layerAt(float2 uv) { return inside(uv) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float aAt(float2 px) { return layerAt(px / layer).a; }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float2 p = uv * W;
        float4 orig = layerAt(uv);
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        float z = max(scale * 2.0, 0.002);
        float2 pc = (uv - 0.5) * W;
        float2 q = nmStd(float2(pc.x, -pc.y), pxs);
        q.y = -q.y;
        float an = radians(-direction);
        float2 dir = float2(cos(an), sin(an));
        float2 nrm = float2(-dir.y, dir.x);
        float2 ns = nmRot(nrm, -radians(angle));
        float ext = 0.5 * (abs(W.x * ns.x) + abs(W.y * ns.y)) / z;
        float wd = max(width, 0.0);
        float off = prog(offset);
        if ((autop>0.5)) off = fract(off * 0.5 + 0.5) * 2.0 - 1.0;
        float2 C = nrm * off * (ext + wd);
        float d = abs(dot(q - C, nrm));
        float x = d / max(wd * 0.5, 1e-3);
        float prof;
        if (int(shape) == 0) prof = clamp(1.0 - x, 0.0, 1.0);
        else if (int(shape) == 1) prof = x < 1.0 ? 0.5 + 0.5 * cos(3.14159265 * x) : 0.0;
        else prof = clamp((wd * 0.5 - d) + 0.5, 0.0, 1.0);
        float e = 0.0;
        float t = max(edgeThick, 0.0);
        if (t > 0.0 && orig.a > 0.0 && prof > 0.0) {
            float m = 1.0;
            float nd = max(4.0, floor(8.0 * qMul() + 0.5));
            for (int i = 0; i < 16; i++) {
                if (float(i) >= nd) break;
                float a = float(i) * 6.2831853 / nd;
                m = min(m, aAt(p + float2(cos(a), sin(a)) * t));
                m = min(m, aAt(p + float2(cos(a), sin(a)) * t * 0.5));
            }
            e = clamp(orig.a - m, 0.0, 1.0);
        }
        float I = (prof * max(sweepInt, 0.0) + e * prof * max(edgeInt, 0.0)) * orig.a;
        float Ic = clamp(I, 0.0, 1.0);
        float4 fx = nmGradMap(float4(float3(Ic), Ic));
        if (int(blendMode) == 5) {
            float4 f = clamp(fx * hardness, 0.0, 1.0) * clamp(alpha, 0.0, 1.0);
            float4 b = orig * clamp(alphaComp, 0.0, 1.0);
            float m = clamp(prof, 0.0, 1.0);
            float4 o = clamp(float4(b.rgb * m + f.rgb, b.a * m), 0.0, 1.0);
            amzOutput = float4(min(o.rgb, float3(o.a)), o.a);
        } else amzOutput = nmBlend(orig, fx);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
